'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(hasMain=true){const events=[],classes=new Set();function element(name,selector=''){return {tagName:name.toUpperCase(),selector,children:[],scrollTop:0,scrollLeft:0,inert:false,classList:{add:n=>classes.add(n),remove:n=>classes.delete(n)},matches:s=>s.split(',').includes(selector),append(...items){for(const item of items){for(const parent of [body,...created])parent.children=parent.children.filter(c=>c!==item);this.children.push(item);}},prepend(item){this.children.unshift(item);},addEventListener(name,callback){this[name]=callback;},scrollTo(x,y){if(typeof x==='object'){this.scrollTop=x.top??this.scrollTop;this.scrollLeft=x.left??this.scrollLeft;}else{this.scrollLeft=x;this.scrollTop=y;}}};}const created=[],body={children:[]};const header=element('header','.guide-bar'),main=element('main','main'),footer=element('footer','.site-footer'),other=element('div','.other');body.children=hasMain?[header,main,footer,other]:[header,footer];body.prepend=item=>body.children.unshift(item);body.append=item=>body.children.push(item);const document={body,documentElement:{classList:{add:n=>classes.add(n)}},createElement(tag){const e=element(tag);created.push(e);return e;}};const window={dispatchEvent:e=>events.push(e.type)};vm.runInNewContext(fs.readFileSync('guide-viewport.js','utf8'),{window,document,Event:class{constructor(type){this.type=type;}}});return {api:window.PhoenixViewport,body,header,main,footer,other,events,classes};}
test('reading viewport contains all page landmarks while dock and overlays stay outside',()=>{const x=setup();assert.deepEqual(x.api.reader.children,[x.header,x.main,x.footer]);assert.ok(x.body.children.includes(x.api.dock));assert.ok(x.body.children.includes(x.other));assert.ok(x.classes.has('phoenix-viewport-ready'));});
test('route scroll coordinates and option-based scrolling use the reading viewport',()=>{const {api}=setup();api.scrollTo(0,321);assert.equal(api.scrollY,321);api.scrollTo({top:765,left:12});assert.equal(api.scrollY,765);assert.equal(api.scrollX,12);});
test('navigation lock preserves reading position and scroll events reach existing route listeners',()=>{const {api,events,classes}=setup();api.scrollTo(0,444);api.lock();assert.equal(api.reader.inert,true);assert.ok(classes.has('is-locked'));assert.equal(api.scrollY,444);api.unlock();assert.equal(api.reader.inert,false);assert.equal(classes.has('is-locked'),false);api.reader.scroll();assert.deepEqual(events,['scroll']);});
test('missing page landmarks leave the document layout unchanged',()=>{const x=setup(false);assert.equal(x.api,undefined);assert.equal(x.classes.has('phoenix-viewport-ready'),false);});
